#include <iostream>
#include "cpp17/Geo2/PolygonConvex.hpp"

using i64 = long long;

int main() {
    std::ios::sync_with_stdio(false);
    std::cin.tie(nullptr);
    int n;
    std::cin >> n;
    std::vector<Point<i64>> points(n);
    for (auto &p : points) std::cin >> p;
    auto hull = convexHull(std::move(points));
    std::cout << hull.size() << '\n';
    for (const auto &p : hull)
        std::cout << p.x << ' ' << p.y << '\n';
}

